"""Provenance metadata for surrogate Structured Text generated by st_gen.

The Structured Text emitted by st_gen is a *surrogate*: it is reconstructed
from an EPANET INP model plus a DHALSIM-style ``plcs.yaml`` sensor/actuator
assignment.  It is **not** the original vendor or benchmark PLC source code
(EPANET/DHALSIM ships no PLC source at all), so every artifact we publish must
say so explicitly.  This module owns the constants and the small helpers used
to build that statement.
"""

from __future__ import annotations

import hashlib
from pathlib import Path

#: Name of the generator recorded in the manifest.
GENERATOR_NAME = "st_gen"

#: Version of the generator recorded in the manifest (matches pyproject).
GENERATOR_VERSION = "0.1.0"

#: Upstream project the topologies are derived from.
UPSTREAM_NAME = "DHALSIM"

#: Upstream project URL.
UPSTREAM_URL = "https://github.com/Critical-Infrastructure-Systems-Lab/DHALSIM"

#: Pinned upstream commit.
UPSTREAM_COMMIT = "51a5e00f65cdd666b9aec10d3c928ea40ad1b53d"

#: Machine-readable statement that the ST is a surrogate.
SURROGATE_STATEMENT = (
    "SURROGATE Structured Text: reconstructed by st_gen from the EPANET INP "
    "model and a DHALSIM-style plcs.yaml. This is NOT the original vendor or "
    "benchmark PLC source code and must not be presented as such."
)

#: Lines injected into the header comment of every generated .st file.
#: Kept in sync with :data:`SURROGATE_STATEMENT` — the header is the version
#: a reader sees when the manifest is not at hand.
SURROGATE_HEADER_LINES = (
    "SURROGATE Structured Text: reconstructed by st_gen from the EPANET INP model",
    "and a DHALSIM-style plcs.yaml. This is NOT the original vendor or benchmark",
    "PLC source code and must not be presented as such.",
    f"Upstream: {UPSTREAM_NAME} {UPSTREAM_URL} @ {UPSTREAM_COMMIT}",
)

#: Supported / unsupported control forms.
SUPPORTED_CONTROLS = (
    "simple node controls only: "
    "LINK <id> OPEN|CLOSED IF NODE <id> BELOW|ABOVE <threshold>"
)

UNSUPPORTED_CONTROLS = (
    "[RULES] sections (st_gen raises UnsupportedRulesError)",
    "time-based controls (e.g. 'AT TIME <h>:<m>')",
    "numeric / setpoint controls (e.g. 'SET <id> TO <value>')",
    "controls whose (comparator, threshold) pair is ambiguous between OPEN and CLOSED",
)

#: Human-readable limitations block recorded in the manifest.
CONTROL_LIMITATIONS = [
    f"supported: {SUPPORTED_CONTROLS}",
    *[f"unsupported: {item}" for item in UNSUPPORTED_CONTROLS],
]


def sha256_file(path: str | Path) -> str | None:
    """Return the SHA256 hex digest of *path*, or None if it cannot be read."""
    try:
        data = Path(path).read_bytes()
    except OSError:
        return None
    return hashlib.sha256(data).hexdigest()


def upstream_block() -> dict:
    """Return the upstream (DHALSIM) provenance block."""
    return {
        "project": UPSTREAM_NAME,
        "url": UPSTREAM_URL,
        "commit": UPSTREAM_COMMIT,
    }


def generator_block() -> dict:
    """Return the generator name/version block."""
    return {"name": GENERATOR_NAME, "version": GENERATOR_VERSION}
